interface ISpeaker { string Speak(); }
record Dog : ISpeaker { public string Speak() => "Woaf"; }
record Cat : ISpeaker { public string Speak() => "Mew"; }

object[] items = { 42, "hello", 3.14 };
foreach (var item in items)
{
    switch (item)
    {
        case int i: Console.WriteLine($"int: {i}"); break;
        case string s: Console.WriteLine($"string: {s}"); break;
        case double d: Console.WriteLine($"float64: {d}"); break;
    }
}
